#!/usr/bin/env python3
import sys
import math
from decimal import *

def solve(A: int, B: int):
    A = Decimal(str(A))
    B = Decimal(str(B))
    s8 = Decimal('0.08')
    s10 = Decimal('0.10')
    n8 = [math.ceil(A/s8), math.floor((A+1)/s8)]
    n10 = [math.ceil(B/s10), math.floor((B+1)/s10)]

    # print(n8, n10)
    if n10[0] <= n8[0] < n10[1]:
        print(int(n8[0]))
    elif n8[0] <= n10[0] < n8[1]:
        print(int(n10[0]))
    else:
        print('-1')
    return


# Generated by 1.1.7.1 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    A = int(next(tokens))  # type: int
    B = int(next(tokens))  # type: int
    solve(A, B)

if __name__ == '__main__':
    main()
